export const products:Product[]=seed.flatMap((p,i)=>{const images=suppliedImages[p.name];if(!images?.catalog)return[];const gallery=[...new Set(Object.values(images).filter((src):src is string=>Boolean(src)))],prices=[Math.round(p.price*.62/500)*500,Math.round(p.price*.8/500)*500,p.price],sizes=p.setCount?[{volume:`${p.setCount}-piece set`,price:p.price,inStock:true}]:[{volume:"30 ml",price:prices[0],inStock:true},{volume:"50 ml",price:prices[1],inStock:true},{volume:"75 ml",price:Math.round(p.price*.9/500)*500,inStock:true},{volume:"100 ml",price:prices[2],inStock:i!==3}];return[{...p,id:`aur-${i+1}`,currency:"NGN",image:images.catalog,images,gallery,sizes,reviews,gender:"Unisex",stockStatus:i===3?"Low Stock":"In Stock"}]})
export const families=["Floral","Woody","Amber","Oud","Citrus","Fresh"] as const
export const normalizeSearch=(value:string)=>value.normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase()
export const formatPrice=(value:number)=>new Intl.NumberFormat("en-NG",{style:"currency",currency:"NGN",maximumFractionDigits:0}).format(value)
export const getStartingPrice=(product:Product)=>{
 const prices=product.sizes.filter(size=>size.inStock).map(size=>size.price)
 return prices.length?Math.min(...prices):product.price
}
export const collections=[...new Set(products.map(product=>product.collection))].sort()
export const getProduct=(slug:string)=>products.find(p=>p.slug===slug)
export function relatedProducts(product:Product,limit=4){const notes=new Set([...product.topNotes,...product.heartNotes,...product.baseNotes]);return products.filter(p=>p.id!==product.id&&Boolean(p.setCount)===Boolean(product.setCount)).map(p=>({p,score:(p.fragranceFamily===product.fragranceFamily?3:0)+(p.intensity===product.intensity?1:0)+(p.collection===product.collection?1:0)+[...p.topNotes,...p.heartNotes,...p.baseNotes].filter(n=>notes.has(n)).length})).sort((a,b)=>b.score-a.score).slice(0,limit).map(x=>x.p)}
